const $=id=>document.getElementById(id);
const norm=s=>String(s).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const artists=s=>new Set(String(s).split(';').map(a=>a.trim().toLowerCase()).filter(Boolean));
const artistSets=DATA.songs.map(s=>artists(s[2]));
const searchIndex=DATA.songs.map(s=>norm(s[1]+' '+s[2]));
let chosen=DATA.initial;
let searchMatches=[];
const key=()=>$('model').value+'_'+$('space').value;
function sharedArtist(a,b){for(const x of artistSets[a])if(artistSets[b].has(x))return true;return false;}
function retrieve(config,forceCluster=false){
 const space=DATA.specs[config].space, matrix=DATA.matrices[space], q=matrix[chosen], labels=DATA.labels[config];
 const same=forceCluster||$('scope').value==='cluster';
 const candidates=[];
 for(let i=0;i<DATA.train_size;i++){
  if(i===chosen||DATA.songs[i][0]===DATA.songs[chosen][0])continue;
  if(same&&labels[i]!==labels[chosen])continue;
  if($('differentArtist').checked&&sharedArtist(i,chosen))continue;
  if($('lessPopular').checked&&(DATA.songs[i][3]===null||DATA.songs[chosen][3]===null||DATA.songs[i][3]>=DATA.songs[chosen][3]))continue;
  let d=0;for(let j=0;j<q.length;j++){let diff=q[j]-matrix[i][j];d+=diff*diff;}
  candidates.push({index:i,distance:Math.sqrt(d)});
 }
 candidates.sort((a,b)=>a.distance-b.distance||a.index-b.index);
 return {total:candidates.length,items:candidates.slice(0,10)};
}
function choose(index){chosen=index;$('matches').replaceChildren();$('search').value='';$('searchInfo').textContent='Canción seleccionada. Puedes buscar otra en cualquier momento.';render();}
function render(){
 const config=key(), song=DATA.songs[chosen], profile=DATA.labels[config][chosen];
 $('configuration').textContent=DATA.specs[config].family+' · '+($('space').value==='pca'?'PCA':'Original');
 const featureLabels=[['Energía',1],['Bailabilidad',0],['Acústica',4],['Instrumental',5],['Valencia',7]];
 $('seed').innerHTML='<div class="eyebrow">Tu canción</div><div class="trackname">'+esc(song[1])+'</div><div class="artist">'+esc(song[2].split(';').join(' · '))+'</div><div class="profile">Perfil '+profile+' · '+esc(DATA.specs[config].names[profile])+'</div><div class="tags">'+esc(song[4])+' · Popularidad '+(song[3]??'s/d')+'/100 · '+(song[5]==='test'?'Prueba':'Entrenamiento')+'</div>'+featureLabels.map(([label,pos])=>'<div class="barrow"><span>'+label+'</span><span class="bar"><i style="width:'+Math.max(0,Math.min(100,DATA.raw[chosen][pos]*100))+'%"></i></span><span>'+Math.round(DATA.raw[chosen][pos]*100)+'</span></div>').join('')+'<p class="note">Tempo: '+DATA.raw[chosen][8].toFixed(1)+' BPM · Duración: '+(DATA.raw[chosen][9]/60000).toFixed(2)+' min</p>';
 const answer=retrieve(config);
 $('status').textContent=answer.items.length+' sugerencias entre '+answer.total.toLocaleString('es')+' candidatas'+($('scope').value==='all'?' · Sin restricción de grupo':' · Mismo perfil sonoro');
 if(!answer.items.length){$('results').innerHTML='<div class="empty">No hay canciones que cumplan estos filtros. Desactiva “Menor popularidad” o amplía la búsqueda a todos los perfiles.</div>';}
 else $('results').innerHTML=answer.items.map(({index:i,distance},rank)=>{let s=DATA.songs[i];return '<article class="track"><div class="number">'+String(rank+1).padStart(2,'0')+'</div><div><div class="songtitle">'+esc(s[1])+'</div><p class="artist">'+esc(s[2].split(';').join(' · '))+'</p><div class="tags">'+esc(s[4])+' · Popularidad '+(s[3]??'s/d')+'/100</div></div><div class="actions"><a class="listen" href="https://open.spotify.com/track/'+encodeURIComponent(s[0])+'" target="_blank" rel="noopener noreferrer">Abrir en Spotify ↗</a><button class="use" data-song="'+i+'">Explorar desde aquí</button><span class="distance">Distancia '+distance.toFixed(3)+'</span></div></article>';}).join('');
 $('results').querySelectorAll('[data-song]').forEach(button=>button.addEventListener('click',()=>choose(Number(button.dataset.song))));
 const active=retrieve(config,true), ids=new Set(active.items.map(x=>x.index));
 $('liveComparison').innerHTML=Object.keys(DATA.specs).map(k=>{let a=retrieve(k,true), l=DATA.labels[k][chosen], matches=a.items.filter(x=>ids.has(x.index)).length;return '<tr class="'+(k===config?'active':'')+'"><td>'+esc(DATA.specs[k].family+' / '+DATA.specs[k].space)+'</td><td>'+l+'</td><td>'+a.total.toLocaleString('es')+'</td><td>'+matches+' de '+active.items.length+'</td></tr>';}).join('');
}
$('search').addEventListener('input',()=>{const value=norm($('search').value.trim());$('matches').replaceChildren();searchMatches=[];if(value.length<2){$('searchInfo').textContent='Escribe al menos dos caracteres.';return;}for(let i=0;i<searchIndex.length&&searchMatches.length<20;i++)if(searchIndex[i].includes(value))searchMatches.push(i);$('searchInfo').textContent=searchMatches.length?'Hasta 20 coincidencias. Selecciona una o pulsa Enter para elegir la primera.':'No hay coincidencias en esta muestra. Prueba otro título o artista.';for(const i of searchMatches){const b=document.createElement('button');b.className='match';b.type='button';b.innerHTML=esc(DATA.songs[i][1])+'<small>'+esc(DATA.songs[i][2])+'</small>';b.addEventListener('click',()=>choose(i));$('matches').append(b);}});
$('search').addEventListener('keydown',event=>{if(event.key==='Enter'&&searchMatches.length){event.preventDefault();choose(searchMatches[0]);}if(event.key==='Escape')$('matches').replaceChildren();});
for(const id of ['model','space','scope','differentArtist','lessPopular'])$(id).addEventListener('change',render);
document.addEventListener('click',e=>{if(!e.target.closest('.searchwrap'))$('matches').replaceChildren();});
$('catalogBadge').textContent=DATA.songs.length.toLocaleString('es')+' canciones';$('pcaBadge').textContent='PCA: '+DATA.pca.components+' componentes · '+(100*DATA.pca.variance).toFixed(1)+' %';
$('metrics').innerHTML=DATA.comparison.filter(r=>r.split==='train'&&r.evaluation_space==='original').map(r=>'<tr><td>'+esc(r.model)+'</td><td>'+esc(r.space)+'</td><td>'+r.groups+'</td><td>'+r.silhouette.toFixed(4)+'</td><td>'+r.davies_bouldin.toFixed(3)+'</td><td>'+r.calinski_harabasz.toFixed(1)+'</td></tr>').join('');
render();
